content:
:root {
  --bg-primary: #0f172a;
  --bg-secondary: #1e293b;
  --bg-tertiary: #334155;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --accent-blue: #38bdf8;
  --accent-cyan: #22d3ee;
  --accent-emerald: #10b981;
  --accent-rose: #f43f5e;
  --key-bg: #1e293b;
  --key-border: #475569;
  --key-active-bg: #38bdf8;
  --key-active-text: #0f172a;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Hiragino Sans', 'Noto Sans JP', sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Consolas', monospace;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.2), 0 2px 4px -2px rgba(0, 0, 0, 0.2);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.3), 0 4px 6px -4px rgba(0, 0, 0, 0.3);
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-primary);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  overflow-x: hidden;
  user-select: none;
  -webkit-user-select: none;
}

/* アプリ全体レイアウト */
.typing-app {
  width: 100%;
  max-width: 900px;
  min-height: 100vh;
  margin: 0 auto;
  padding: 1.25rem 1rem 2rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
}

/* ヘッダー */
.app-header {
  text-align: center;
  margin-bottom: 1.5rem;
  width: 100%;
}

.header-title {
  font-size: 1.85rem;
  font-weight: 800;
  letter-spacing: -0.025em;
  background: linear-gradient(135deg, #38bdf8 0%, #818cf8 50%, #c084fc 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 0.35rem;
}

.header-subtitle {
  font-size: 0.875rem;
  color: var(--text-muted);
  font-weight: 500;
}

/* 統計・ステータスバー */
.stat-bar {
  display: flex;
  justify-content: center;
  gap: 1rem;
  width: 100%;
  max-width: 720px;
  margin-bottom: 1.5rem;
  flex-wrap: wrap;
}

.stat-badge {
  background-color: var(--bg-secondary);
  border: 1px solid var(--bg-tertiary);
  border-radius: 0.75rem;
  padding: 0.5rem 1rem;
  display: flex;
  align-items: center;
  gap: 0.6rem;
  min-width: 110px;
  box-shadow: var(--shadow-sm);
  transition: all 0.2s ease;
}

.stat-label {
  font-size: 0.75rem;
  color: var(--text-muted);
  text-transform: uppercase;
  font-weight: 600;
}

.stat-value {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-main);
  font-family: var(--font-mono);
}

.timer-badge {
  border-color: rgba(56, 189, 248, 0.4);
  background-color: rgba(56, 189, 248, 0.08);
}

.timer-warning {
  border-color: rgba(244, 63, 94, 0.6);
  background-color: rgba(244, 63, 94, 0.15);
  animation: pulse-warning 1s infinite alternate;
}

.timer-warning .stat-value {
  color: #fb7185;
}

@keyframes pulse-warning {
  from {
    transform: scale(1);
    box-shadow: 0 0 5px rgba(244, 63, 94, 0.2);
  }
  to {
    transform: scale(1.03);
    box-shadow: 0 0 15px rgba(244, 63, 94, 0.5);
  }
}

/* ゲームカードとお題エリア */
.game-card {
  width: 100%;
  max-width: 720px;
  background-color: var(--bg-secondary);
  border: 1px solid var(--bg-tertiary);
  border-radius: 1.25rem;
  padding: 2.25rem 1.5rem;
  margin-bottom: 1.75rem;
  box-shadow: var(--shadow-lg);
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 200px;
}

.word-display-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  width: 100%;
  z-index: 1;
}

.kanji-text {
  font-size: 2.25rem;
  font-weight: 800;
  color: var(--text-main);
  letter-spacing: 0.05em;
  margin-bottom: 0.35rem;
}

.kana-text {
  font-size: 1.1rem;
  color: var(--accent-cyan);
  margin-bottom: 1rem;
  font-weight: 600;
  letter-spacing: 0.08em;
}

.romaji-text {
  font-family: var(--font-mono);
  font-size: 1.65rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  padding: 0.5rem 1rem;
  background: rgba(15, 23, 42, 0.6);
  border-radius: 0.75rem;
  border: 1px solid rgba(51, 65, 85, 0.6);
  max-width: 100%;
}

.romaji-char {
  display: inline-block;
  transition: all 0.12s ease;
}

.romaji-typed {
  color: var(--accent-emerald);
  opacity: 0.45;
}

.romaji-current {
  color: var(--text-main);
  background-color: rgba(56, 189, 248, 0.35);
  border-bottom: 3px solid var(--accent-blue);
  border-radius: 2px 2px 0 0;
  animation: blink-current 1.2s infinite;
}

@keyframes blink-current {
  0%, 100% {
    background-color: rgba(56, 189, 248, 0.35);
  }
  50% {
    background-color: rgba(56, 189, 248, 0.1);
  }
}

.romaji-remain {
  color: var(--text-muted);
}

.input-helper {
  margin-top: 1rem;
  font-size: 0.8rem;
  color: #64748b;
  display: flex;
  align-items: center;
  gap: 0.35rem;
}

/* スマホ用フォーカス維持の隠しインプット */
.hidden-input {
  position: absolute;
  top: 0;
  left: 0;
  opacity: 0;
  pointer-events: none;
  width: 1px;
  height: 1px;
  font-size: 16px;
}

/* スタート前オーバーレイ */
.start-overlay {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(15, 23, 42, 0.88);
  backdrop-filter: blur(4px);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  z-index: 10;
  border-radius: 1.25rem;
  padding: 1.5rem;
}

.start-button {
  background: linear-gradient(135deg, #38bdf8 0%, #2563eb 100%);
  color: #ffffff;
  border: none;
  border-radius: 9999px;
  padding: 0.9rem 2.5rem;
  font-size: 1.15rem;
  font-weight: 700;
  cursor: pointer;
  box-shadow: 0 4px 15px rgba(37, 99, 235, 0.4);
  transition: all 0.2s ease;
  outline: none;
}

.start-button:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(56, 189, 248, 0.5);
}

.start-button:active {
  transform: translateY(0);
}

.start-instruction {
  margin-top: 1rem;
  color: var(--text-muted);
  font-size: 0.875rem;
  font-weight: 500;
}

/* バーチャルキーボード */
.keyboard-container {
  width: 100%;
  max-width: 760px;
  background: var(--bg-secondary);
  border: 1px solid var(--bg-tertiary);
  border-radius: 1rem;
  padding: 0.85rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  box-shadow: var(--shadow-md);
  margin-top: auto;
}

.keyboard-row {
  display: flex;
  justify-content: center;
  gap: 0.35rem;
  width: 100%;
}

.key-button {
  flex: 1;
  height: 44px;
  background-color: var(--key-bg);
  border: 1px solid var(--key-border);
  border-radius: 0.45rem;
  color: var(--text-main);
  font-family: var(--font-mono);
  font-size: 0.95rem;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  outline: none;
  transition: background-color 0.1s, transform 0.08s, border-color 0.1s;
  box-shadow: 0 2px 0 #0f172a;
}

.key-button:active {
  transform: translateY(2px);
  box-shadow: none;
}

.key-active {
  background-color: var(--key-active-bg);
  color: var(--key-active-text);
  border-color: #7dd3fc;
  font-weight: 800;
  box-shadow: 0 0 12px rgba(56, 189, 248, 0.7), 0 2px 0 #0284c7;
  transform: translateY(-1px);
}

.key-space {
  flex: 4;
}

/* スマホ用キーボード表示トグル */
.touch-toggle-btn {
  background-color: transparent;
  color: var(--text-muted);
  border: 1px solid var(--bg-tertiary);
  border-radius: 0.5rem;
  padding: 0.4rem 0.85rem;
  font-size: 0.8rem;
  font-weight: 500;
  cursor: pointer;
  margin-top: 0.75rem;
  transition: all 0.2s ease;
}

.touch-toggle-btn:hover {
  background-color: var(--bg-secondary);
  color: var(--text-main);
}

/* 結果モーダル */
.result-modal-backdrop {
  position: fixed;
  inset: 0;
  background-color: rgba(15, 23, 42, 0.75);
  backdrop-filter: blur(6px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
  padding: 1rem;
  animation: fadeIn 0.25s ease-out forwards;
}

.result-modal {
  background-color: var(--bg-secondary);
  border: 1px solid var(--bg-tertiary);
  border-radius: 1.5rem;
  padding: 2.25rem 2rem;
  width: 100%;
  max-width: 520px;
  box-shadow: var(--shadow-lg), 0 0 30px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  animation: scaleUp 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.result-title {
  font-size: 1.6rem;
  font-weight: 800;
  color: var(--text-main);
  margin-bottom: 0.5rem;
}

.rank-badge {
  display: inline-block;
  background: linear-gradient(135deg, #f59e0b 0%, #ef4444 100%);
  color: #ffffff;
  padding: 0.35rem 1.25rem;
  border-radius: 9999px;
  font-size: 1.05rem;
  font-weight: 800;
  margin-bottom: 1.5rem;
  box-shadow: 0 4px 10px rgba(245, 158, 11, 0.3);
}

.result-hero {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 0.4rem;
  margin-bottom: 1.75rem;
}

.result-hero-number {
  font-family: var(--font-mono);
  font-size: 4.5rem;
  font-weight: 800;
  line-height: 1;
  background: linear-gradient(135deg, #38bdf8 0%, #3b82f6 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.result-hero-unit {
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--text-muted);
}

.result-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.85rem;
  width: 100%;
  margin-bottom: 2rem;
}

.result-card {
  background-color: var(--bg-primary);
  border: 1px solid var(--bg-tertiary);
  border-radius: 0.85rem;
  padding: 0.9rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.3rem;
}

.result-label {
  font-size: 0.75rem;
  color: var(--text-muted);
  font-weight: 600;
}

.result-card-value {
  font-family: var(--font-mono);
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--text-main);
}

.restart-button {
  width: 100%;
  background: linear-gradient(135deg, #10b981 0%, #059669 100%);
  color: #ffffff;
  border: none;
  border-radius: 0.85rem;
  padding: 0.95rem;
  font-size: 1.1rem;
  font-weight: 700;
  cursor: pointer;
  box-shadow: 0 4px 15px rgba(16, 185, 129, 0.4);
  transition: all 0.2s ease;
  outline: none;
}

.restart-button:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(16, 185, 129, 0.5);
}

.restart-button:active {
  transform: translateY(0);
}

/* アニメーション */
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes scaleUp {
  from {
    opacity: 0;
    transform: scale(0.92);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

/* レスポンシブ対応 (モバイル360px〜) */
@media (max-width: 640px) {
  .typing-app {
    padding: 0.75rem 0.5rem 1.5rem;
  }

  .header-title {
    font-size: 1.5rem;
  }

  .stat-bar {
    gap: 0.4rem;
  }

  .stat-badge {
    min-width: 75px;
    padding: 0.4rem 0.6rem;
    gap: 0.35rem;
  }

  .stat-label {
    font-size: 0.65rem;
  }

  .stat-value {
    font-size: 0.95rem;
  }

  .game-card {
    padding: 1.5rem 0.75rem;
    margin-bottom: 1rem;
    min-height: 170px;
  }

  .kanji-text {
    font-size: 1.75rem;
  }

  .kana-text {
    font-size: 0.95rem;
    margin-bottom: 0.75rem;
  }

  .romaji-text {
    font-size: 1.25rem;
    padding: 0.4rem 0.6rem;
    letter-spacing: 0.08em;
  }

  .keyboard-container {
    padding: 0.45rem;
    gap: 0.35rem;
  }

  .keyboard-row {
    gap: 0.2rem;
  }

  .key-button {
    height: 38px;
    font-size: 0.8rem;
    border-radius: 0.3rem;
  }

  .result-modal {
    padding: 1.5rem 1.25rem;
  }

  .result-hero-number {
    font-size: 3.5rem;
  }
}

export type WordDifficulty = 'easy' | 'medium' | 'hard';

export interface WordItem {
  id: number;
  kanji: string;
  kana: string;
  romaji: string;
  romajiPatterns?: string[];
  category?: string;
  difficulty?: WordDifficulty;
}

export type GameState = 'ready' | 'playing' | 'finished';

export interface TypingStats {
  totalTypedCount: number;
  correctKeyCount: number;
  missKeyCount: number;
  completedWordsCount: number;
  elapsedTime?: number;
}

export interface ResultDetail {
  correctCharCount: number;
  missCharCount: number;
  cpm: number;
  wpm?: number;
  accuracy: number;
  rankTitle: string;
}

export interface VirtualKeyboardProps {
  activeKey: string;
  onKeyPress?: (key: string) => void;
}

export interface ResultModalProps {
  stats: TypingStats;
  onRestart: () => void;
}

import { FC, useMemo, useState, useEffect, useCallback } from 'react';
import { VirtualKeyboardProps } from '../types';

const KEYBOARD_LAYOUT: string[][] = [
  ['1', '2', '3', '4', '5', '6', '7', '8', '9', '0', '-'],
  ['q', 'w', 'e', 'r', 't', 'y', 'u', 'i', 'o', 'p'],
  ['a', 's', 'd', 'f', 'g', 'h', 'j', 'k', 'l'],
  ['z', 'x', 'c', 'v', 'b', 'n', 'm']
];

const VirtualKeyboard: FC<VirtualKeyboardProps> = ({ activeKey = '', onKeyPress }) => {
  const [pressedKey, setPressedKey] = useState<string>('');
  const normalizedActiveKey = useMemo(() => (activeKey || '').toLowerCase(), [activeKey]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      setPressedKey(e.key.toLowerCase());
    };

    const handleKeyUp = () => {
      setPressedKey('');
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  const handleKeyClick = useCallback((key: string) => {
    if (typeof onKeyPress === 'function') {
      onKeyPress(key);
    }
  }, [onKeyPress]);

  return (
    <div className="keyboard-container" aria-label="バーチャルキーボード">
      {KEYBOARD_LAYOUT.map((row, rowIndex) => (
        <div key={rowIndex} className="keyboard-row">
          {row.map((char) => {
            const isTarget = normalizedActiveKey === char;
            const isPhysicallyPressed = pressedKey === char;
            const isActive = isTarget || isPhysicallyPressed;

            return (
              <button
                key={char}
                type="button"
                className={isActive ? 'key-button key-active' : 'key-button'}
                onClick={() => handleKeyClick(char)}
                tabIndex={-1}
                aria-pressed={isActive}
                aria-label={`キー ${char.toUpperCase()}`}
              >
                {char.toUpperCase()}
              </button>
            );
          })}
          {rowIndex === 0 && (
            <button
              type="button"
              className={pressedKey === 'backspace' ? 'key-button key-backspace key-active' : 'key-button key-backspace'}
              onClick={() => handleKeyClick('Backspace')}
              tabIndex={-1}
              aria-label="バックスペースキー"
            >
              BS
            </button>
          )}
        </div>
      ))}
      <div className="keyboard-row">
        <button
          type="button"
          className={
            normalizedActiveKey === ' ' || pressedKey === ' '
              ? 'key-button key-space key-active'
              : 'key-button key-space'
          }
          onClick={() => handleKeyClick(' ')}
          tabIndex={-1}
          aria-label="スペースキー"
          aria-pressed={normalizedActiveKey === ' ' || pressedKey === ' '}
        >
          SPACE
        </button>
      </div>
    </div>
  );
};

export default VirtualKeyboard;

import { FC, useMemo, useEffect } from 'react';
import { ResultModalProps, ResultDetail } from '../types';

const GAME_DURATION_SECONDS = 60;

const getRankTitle = (cpm: number, accuracy: number): string => {
  if (cpm >= 350 && accuracy >= 95) return '神速・達人級';
  if (cpm >= 280 && accuracy >= 90) return '超上級者';
  if (cpm >= 200 && accuracy >= 85) return '上級者';
  if (cpm >= 140 && accuracy >= 80) return '中級者';
  if (cpm >= 80) return '初級者';
  return 'タイピング入門者';
};

const ResultModal: FC<ResultModalProps> = ({ stats, onRestart }) => {
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Enter' || e.key === 'Escape') {
        e.preventDefault();
        if (typeof onRestart === 'function') {
          onRestart();
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [onRestart]);

  const result: ResultDetail = useMemo(() => {
    const totalTyped = stats?.totalTypedCount || 0;
    const correct = stats?.correctKeyCount || 0;
    const miss = stats?.missKeyCount || 0;

    const durationMinutes = GAME_DURATION_SECONDS > 0 ? GAME_DURATION_SECONDS / 60 : 1;
    const cpm = Math.round(correct / durationMinutes);
    const accuracy = totalTyped > 0 ? Math.round((correct / totalTyped) * 100) : 0;
    const rankTitle = getRankTitle(cpm, accuracy);

    return {
      correctCharCount: correct,
      missCharCount: miss,
      cpm,
      accuracy,
      rankTitle,
    };
  }, [stats]);

  const wpm = Math.round(result.cpm / 5);
  const keysPerSec = (result.correctCharCount / GAME_DURATION_SECONDS).toFixed(1);

  return (
    <div className="result-modal-backdrop" role="dialog" aria-modal="true" aria-labelledby="result-heading">
      <div className="result-modal">
        <h2 id="result-heading" className="result-title">タイピング結果</h2>

        <div className="rank-badge">{result.rankTitle}</div>

        <div className="result-hero">
          <span className="result-hero-number">{result.cpm}</span>
          <span className="result-hero-unit">CPM ({wpm} WPM)</span>
        </div>

        <div className="result-grid">
          <div className="result-card">
            <span className="result-label">正解入力数</span>
            <span className="result-card-value">{result.correctCharCount} 文字</span>
          </div>

          <div className="result-card">
            <span className="result-label">ミス入力数</span>
            <span className="result-card-value">{result.missCharCount} 回</span>
          </div>

          <div className="result-card">
            <span className="result-label">正確率</span>
            <span className="result-card-value">{result.accuracy}%</span>
          </div>

          <div className="result-card">
            <span className="result-label">秒間打鍵</span>
            <span className="result-card-value">{keysPerSec} 打/秒</span>
          </div>

          <div className="result-card">
            <span className="result-label">クリア単語数</span>
            <span className="result-card-value">{stats?.completedWordsCount || 0} 個</span>
          </div>

          <div className="result-card">
            <span className="result-label">ワード/分 (WPM)</span>
            <span className="result-card-value">{wpm} WPM</span>
          </div>
        </div>

        <button
          type="button"
          className="restart-button"
          onClick={() => {
            if (typeof onRestart === 'function') {
              onRestart();
            }
          }}
          autoFocus
        >
          もう一度挑戦する (Enter)
        </button>
      </div>
    </div>
  );
};

export default ResultModal;

import { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { GameState, TypingStats, WordItem } from './types';
import { WORDS } from './data/words';
import VirtualKeyboard from './components/VirtualKeyboard';
import ResultModal from './components/ResultModal';

const GAME_DURATION = 60;

const App = () => {
  const [gameState, setGameState] = useState<GameState>('ready');
  const [timeLeft, setTimeLeft] = useState<number>(GAME_DURATION);
  const [currentWordIndex, setCurrentWordIndex] = useState<number>(0);
  const [typedChars, setTypedChars] = useState<string>('');
  const [showKeyboard, setShowKeyboard] = useState<boolean>(true);
  const [inputValue, setInputValue] = useState<string>('');

  const [stats, setStats] = useState<TypingStats>({
    totalTypedCount: 0,
    correctKeyCount: 0,
    missKeyCount: 0,
    completedWordsCount: 0
  });

  const hiddenInputRef = useRef<HTMLInputElement>(null);
  const timerRef = useRef<number | null>(null);
  const isComposingRef = useRef<boolean>(false);

  // シャッフルした単語リスト
  const [shuffledWords, setShuffledWords] = useState<WordItem[]>(() => {
    return [...WORDS].sort(() => Math.random() - 0.5);
  });

  const currentWord: WordItem = shuffledWords[currentWordIndex] || WORDS[0];

  // 単語に対応するローマ字パターンのリスト
  const availablePatterns: string[] = useMemo(() => {
    if (currentWord.romajiPatterns && currentWord.romajiPatterns.length > 0) {
      return currentWord.romajiPatterns;
    }
    return [currentWord.romaji];
  }, [currentWord]);

  // 現在入力済みの文字にマッチするローマ字候補
  const matchedPatterns = useMemo(() => {
    const matched = availablePatterns.filter((pattern) =>
      pattern.toLowerCase().startsWith(typedChars.toLowerCase())
    );
    return matched.length > 0 ? matched : availablePatterns;
  }, [availablePatterns, typedChars]);

  // 画面表示用の目標ローマ字（マッチ候補の先頭、またはデフォルト）
  const targetRomaji = matchedPatterns[0] || currentWord.romaji;
  const currentKey = targetRomaji[typedChars.length] || '';

  // ゲームスタート処理
  const startGame = useCallback(() => {
    const shuffled = [...WORDS].sort(() => Math.random() - 0.5);
    setShuffledWords(shuffled);
    setCurrentWordIndex(0);
    setTypedChars('');
    setInputValue('');
    setTimeLeft(GAME_DURATION);
    setStats({
      totalTypedCount: 0,
      correctKeyCount: 0,
      missKeyCount: 0,
      completedWordsCount: 0
    });
    setGameState('playing');

    if (hiddenInputRef.current) {
      hiddenInputRef.current.focus();
    }
  }, []);

  // タイマーのカウントダウン更新
  useEffect(() => {
    if (gameState !== 'playing') {
      return;
    }

    timerRef.current = window.setInterval(() => {
      setTimeLeft((prev) => Math.max(0, prev - 1));
    }, 1000);

    return () => {
      if (timerRef.current) {
        clearInterval(timerRef.current);
      }
    };
  }, [gameState]);

  // 残り時間0の監視によるゲーム終了処理（副作用分離）
  useEffect(() => {
    if (gameState === 'playing' && timeLeft === 0) {
      if (timerRef.current) {
        clearInterval(timerRef.current);
      }
      setGameState('finished');
    }
  }, [timeLeft, gameState]);

  // キー入力判定処理（複数ローマ字表記揺れ対応）
  const handleInputChar = useCallback((char: string) => {
    if (gameState === 'ready') {
      startGame();
    }

    if (gameState !== 'playing' && gameState !== 'ready') {
      return;
    }

    const inputLower = char.toLowerCase();
    const nextTyped = typedChars + inputLower;

    // 現在のパターン群から nextTyped に前方一致するものを探す
    const nextMatchedPatterns = availablePatterns.filter((pattern) =>
      pattern.toLowerCase().startsWith(nextTyped.toLowerCase())
    );

    if (nextMatchedPatterns.length > 0) {
      // 正解入力
      setStats((prev) => ({
        ...prev,
        totalTypedCount: prev.totalTypedCount + 1,
        correctKeyCount: prev.correctKeyCount + 1
      }));

      // 完全一致するパターンがあるかチェック（単語クリア判定）
      const isWordCompleted = nextMatchedPatterns.some(
        (pattern) => pattern.toLowerCase() === nextTyped.toLowerCase()
      );

      if (isWordCompleted) {
        setStats((prev) => ({
          ...prev,
          completedWordsCount: prev.completedWordsCount + 1
        }));
        setTypedChars('');
        setCurrentWordIndex((prev) => (prev + 1) % shuffledWords.length);
      } else {
        setTypedChars(nextTyped);
      }
    } else {
      // ミス入力
      setStats((prev) => ({
        ...prev,
        totalTypedCount: prev.totalTypedCount + 1,
        missKeyCount: prev.missKeyCount + 1
      }));
    }
  }, [gameState, startGame, typedChars, availablePatterns, shuffledWords.length]);

  // モバイル入力などの文字列処理
  const processInputString = useCallback((text: string) => {
    for (const char of text) {
      handleInputChar(char);
    }
  }, [handleInputChar]);

  // グローバルキーボードイベント
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (gameState === 'finished') {
        if (e.key === 'Enter') {
          e.preventDefault();
          startGame();
        }
        return;
      }

      if (e.key === 'Tab' || e.altKey || e.ctrlKey || e.metaKey) {
        return;
      }

      if (e.key === 'Enter' || e.key === ' ') {
        if (gameState === 'ready') {
          e.preventDefault();
          startGame();
          return;
        }
      }

      if (e.key.length === 1) {
        e.preventDefault();
        handleInputChar(e.key);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [gameState, handleInputChar, startGame]);

  // 画面クリックで隠しinputにフォーカス
  const handleAppClick = () => {
    if (hiddenInputRef.current) {
      hiddenInputRef.current.focus();
    }
  };

  const isTimerWarning = gameState === 'playing' && timeLeft <= 10;
  const currentAccuracy = stats.totalTypedCount > 0
    ? Math.round((stats.correctKeyCount / stats.totalTypedCount) * 100)
    : 100;

  return (
    <div className="typing-app" onClick={handleAppClick}>
      {/* 隠しインプット（モバイルキーボード・IME対応） */}
      <input
        ref={hiddenInputRef}
        type="text"
        className="hidden-input"
        aria-hidden="true"
        autoCapitalize="off"
        autoComplete="off"
        autoCorrect="off"
        spellCheck={false}
        inputMode="text"
        value={inputValue}
        onCompositionStart={() => {
          isComposingRef.current = true;
        }}
        onCompositionEnd={(e) => {
          isComposingRef.current = false;
          processInputString(e.data);
          setInputValue('');
        }}
        onChange={(e) => {
          if (!isComposingRef.current) {
            processInputString(e.target.value);
            setInputValue('');
          } else {
            setInputValue(e.target.value);
          }
        }}
      />

      <header className="app-header">
        <h1 className="header-title">60秒タイピングチャレンジ</h1>
        <p className="header-subtitle">ローマ字入力で制限時間内に多くの文字をタイプしよう</p>
      </header>

      {/* ステータスバー */}
      <div className="stat-bar">
        <div className={isTimerWarning ? 'stat-badge timer-badge timer-warning' : 'stat-badge timer-badge'}>
          <span className="stat-label">残り時間</span>
          <span className="stat-value">{timeLeft}s</span>
        </div>

        <div className="stat-badge">
          <span className="stat-label">打鍵数</span>
          <span className="stat-value">{stats.correctKeyCount}</span>
        </div>

        <div className="stat-badge">
          <span className="stat-label">ミス</span>
          <span className="stat-value">{stats.missKeyCount}</span>
        </div>

        <div className="stat-badge">
          <span className="stat-label">正確率</span>
          <span className="stat-value">{currentAccuracy}%</span>
        </div>

        <div className="stat-badge">
          <span className="stat-label">クリア数</span>
          <span className="stat-value">{stats.completedWordsCount}</span>
        </div>
      </div>

      {/* メインゲームカード */}
      <div className="game-card">
        {gameState === 'ready' && (
          <div className="start-overlay">
            <button
              type="button"
              className="start-button"
              onClick={(e) => {
                e.stopPropagation();
                startGame();
              }}
            >
              ゲーム開始
            </button>
            <p className="start-instruction">Spaceキーまたは任意のキーを押してもスタートできます</p>
          </div>
        )}

        <div className="word-display-container">
          <div className="kanji-text">{currentWord.kanji}</div>
          <div className="kana-text">{currentWord.kana}</div>

          <div className="romaji-text" aria-label={`入力文字列: ${targetRomaji}`}>
            {targetRomaji.split('').map((char, index) => {
              let charClass = 'romaji-char romaji-remain';
              if (index < typedChars.length) {
                charClass = 'romaji-char romaji-typed';
              } else if (index === typedChars.length) {
                charClass = 'romaji-char romaji-current';
              }

              return (
                <span key={index} className={charClass}>
                  {char}
                </span>
              );
            })}
          </div>

          <div className="input-helper">
            <span>次に打つキー:</span>
            <strong>{currentKey ? currentKey.toUpperCase() : '完了'}</strong>
          </div>
        </div>
      </div>

      {/* キーボードトグル */}
      <button
        type="button"
        className="touch-toggle-btn"
        onClick={(e) => {
          e.stopPropagation();
          setShowKeyboard(!showKeyboard);
        }}
      >
        {showKeyboard ? 'バーチャルキーボードを隠す' : 'バーチャルキーボードを表示'}
      </button>

      {/* バーチャルキーボード */}
      {showKeyboard && (
        <VirtualKeyboard
          activeKey={currentKey}
          onKeyPress={(key) => handleInputChar(key)}
        />
      )}

      {/* 結果モーダル */}
      {gameState === 'finished' && (
        <ResultModal stats={stats} onRestart={startGame} />
      )}
    </div>
  );
};

export default App;
